const assert = require('node:assert/strict');
const { Store, KEY } = require('./model.js');
const memory = () => { const data = new Map(); return { getItem: key => data.get(key) ?? null, setItem: (key, value) => data.set(key, value) }; };
const storage = memory();
let lab = new Store(storage);
assert.equal(lab.search().length, 4);
assert.deepEqual(lab.search('R-104').map(order => order.name), ['Marina']);
assert.deepEqual(lab.search('andre').map(order => order.id), ['R-107']);
assert.deepEqual(lab.search('', 'revelacao').map(order => order.id), ['R-105']);
assert.equal(lab.search('Tiago', 'recebido').length, 0);
lab.advance('R-104', 0);
assert.equal(lab.order('R-104').stage, 1);
assert.throws(() => lab.advance('R-104', 0), /etapa mudou/);
lab = new Store(storage);
assert.equal(lab.order('R-104').stage, 1);
lab.undo();
assert.equal(lab.order('R-104').stage, 0);
assert.equal(new Store(storage).order('R-104').stage, 0);
assert.throws(() => lab.undo(), /Não há/);
lab.updateNote('R-104', '  Guardar margens.  ');
assert.equal(new Store(storage).order('R-104').note, 'Guardar margens.');
lab.updateNote('R-104', 'Guardar margens.');
assert.equal(lab.snapshot().lastChange.before, '');
lab.undo();
assert.equal(lab.order('R-104').note, '');
assert.throws(() => lab.advance('R-107', 3), /já está pronto/);
assert.throws(() => lab.updateNote('R-104', 'a'.repeat(2001)), /2000/);
for (const stage of [0, 1, 2]) lab.advance('R-104', stage);
assert.equal(new Store(storage).order('R-104').stage, 3);
const blocked = new Store({ getItem: () => null, setItem: () => { throw new Error('blocked'); } });
assert.throws(() => blocked.advance('R-104', 0), /não foi aplicada/);
assert.equal(blocked.order('R-104').stage, 0);
const corrupt = memory(); corrupt.setItem(KEY, '{not json');
assert.ok(new Store(corrupt).warning);
console.log('PASS: pesquisa, filtro combinado, avanço completo, etapa terminal, revisão obsoleta, notas, limite, persistência, desfazer, armazenamento bloqueado e dados inválidos.');
